const HASH_BITS=64,HISTORY_LIMIT=25;export class LandmarkRecognitionEngine{constructor(t={}){this.landmarks=t.landmarks||[],this.history=Array.isArray(t.history)?t.history.slice(0,25):[],this.minConfidence="number"==typeof t.minConfidence?t.minConfidence:.55}static hammingDistance(t,n){if("string"!=typeof t||"string"!=typeof n)return-1;if(t.length!==n.length||0===t.length)return-1;let e=0;for(let i=0;i<t.length;i++)t[i]!==n[i]&&e++;return e}static distanceToConfidence(t,n=64){return t<0||n<=0?0:Math.max(0,1-t/n)}static isValidHash(t){return"string"==typeof t&&t.length>0&&/^[01]+$/.test(t)}identify(t,n={}){const e=n.topN||5;if(!LandmarkRecognitionEngine.isValidHash(t))return{matches:[],best:null,isConfident:!1,error:"invalid_hash"};const i=this.landmarks.filter(n=>LandmarkRecognitionEngine.isValidHash(n.hash)&&n.hash.length===t.length).map(n=>{const e=LandmarkRecognitionEngine.hammingDistance(t,n.hash);return{landmark:n,distance:e,confidence:LandmarkRecognitionEngine.distanceToConfidence(e,t.length)}}).sort((t,n)=>t.distance-n.distance).slice(0,e),a=i[0]||null;return{matches:i,best:a,isConfident:!!a&&a.confidence>=this.minConfidence}}addToHistory(t){if(!t||!t.landmarkId)return null;const n={landmarkId:t.landmarkId,landmarkName:t.landmarkName||t.landmarkId,confidence:"number"==typeof t.confidence?t.confidence:null,timestamp:t.timestamp||Date.now()};return this.history.unshift(n),this.history.length>25&&(this.history.length=25),n}getHistory(){return this.history.slice()}clearHistory(){this.history=[]}static getRelatedDestinations(t,n=[]){return t?Array.isArray(n)&&n.length>0?n.filter(n=>n.state===t.state&&n.name!==t.city).slice(0,5).map(t=>({name:t.name,state:t.state,highlights:t.highlights||[]})):(t.nearbyAttractions||[]).map(n=>({name:n,state:t.state,highlights:[]})):[]}}export const RECOGNITION_CONSTANTS={HASH_BITS:64,HISTORY_LIMIT:25};